CREATE TABLE "DigitalTwin" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE CASCADE,"workspaceId" UUID NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE,"name" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"activeVersionId" UUID,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "DigitalTwin_scope_idx" ON "DigitalTwin"("tenantId","workspaceId");
CREATE TABLE "TwinVersion" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"twinId" UUID NOT NULL REFERENCES "DigitalTwin"("id") ON DELETE CASCADE,"versionNumber" INTEGER NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"definition" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("twinId","versionNumber"));
ALTER TABLE "DigitalTwin" ADD CONSTRAINT "DigitalTwin_activeVersionId_fkey" FOREIGN KEY ("activeVersionId") REFERENCES "TwinVersion"("id") ON DELETE SET NULL;
CREATE TABLE "TwinEntity" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"twinId" UUID NOT NULL REFERENCES "DigitalTwin"("id") ON DELETE CASCADE,"versionId" UUID NOT NULL REFERENCES "TwinVersion"("id") ON DELETE RESTRICT,"key" TEXT NOT NULL,"typeKey" TEXT NOT NULL,"attributes" JSONB NOT NULL DEFAULT '{}',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("twinId","key"));
CREATE INDEX "TwinEntity_version_idx" ON "TwinEntity"("twinId","versionId");
CREATE TABLE "TwinEntityState" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"tenantId" UUID NOT NULL,"workspaceId" UUID NOT NULL,"twinId" UUID NOT NULL REFERENCES "DigitalTwin"("id") ON DELETE CASCADE,"entityId" UUID NOT NULL REFERENCES "TwinEntity"("id") ON DELETE CASCADE,"state" JSONB NOT NULL,"provenance" JSONB NOT NULL,"observedAt" TIMESTAMP(3) NOT NULL,"effectiveAt" TIMESTAMP(3) NOT NULL,"ingestedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "TwinEntityState_scope_observed_idx" ON "TwinEntityState"("tenantId","workspaceId","twinId","entityId","observedAt" DESC);
